import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [n, m] = input[0].split(" ").map(Number);
const graph: number[][] = Array.from({ length: n + 1 }, () => []);
for (let i = 1; i <= m; i++) {
  const [u, v] = input[i].split(" ").map(Number);
  graph[u].push(v);
  graph[v].push(u);
}

// color: 0 = 未塗装、1 = 白、-1 = 黒
const color = new Int8Array(n + 1);
let ok = true;
for (let s = 1; s <= n && ok; s++) {
  if (color[s] !== 0) continue;
  // 連結成分ごとに BFS で交互に塗る
  color[s] = 1;
  const queue = [s];
  for (let head = 0; head < queue.length && ok; head++) {
    const v = queue[head];
    for (const next of graph[v]) {
      if (color[next] === 0) {
        color[next] = -color[v];
        queue.push(next);
      } else if (color[next] === color[v]) {
        ok = false; // 隣り合う 2 頂点が同じ色になった
        break;
      }
    }
  }
}
console.log(ok ? "Yes" : "No");
